local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.questGreeting
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.questGreeting = text
end
local rows = text.templates
rows[#rows+1]={"$C, eh? I am Krazek, Baron Revilgaz's secretary. I know everything about the goings on in this jungle and beyond. Perhaps you'd be interested in knowing the going price on oil in Ratchet? No? Looking for work, maybe? I can help you there.","$C이신가? 나는 레빌가즈 남작의 비서인 크라제크라고 하네. 이 밀림과 그 너머에서 일어나는 모든 일을 알고 있지. 톱니항의 기름 시세가 궁금한가? 아닌가? 일거리를 찾고 있는 건가? 그렇다면 내가 도움을 줄 수 있지."}
rows[#rows+1]={"Ach, it's hard enough keeping order around here without all these new troubles popping up!  I hope you have good news, $n...","어이쿠, 이런 새로운 문제들이 끊이지 않으니 이 근방의 질서를 유지하기가 보통 힘든 게 아닙니다! $n님, 부디 좋은 소식을 가져오셨기를 바랍니다..."}
rows[#rows+1]={"Aha!  Good day, good day, Master $C!  Come, sit down and have a drink.  You have an enterprising look in your eye, and I think you'll find speaking to me worth your time...","아하! 좋은 날입니다, $C님! 이리 와서 앉아 술이라도 한잔하세요. 눈빛을 보니 수완이 아주 좋아 보이시는데, 나와 대화를 나누는 게 결코 시간 낭비가 아니라는 걸 알게 되실 겁니다..."}
rows[#rows+1]={"At ease, $C.  If you are just passing though I suggest you stick to the roads and only travel by day. If your business is here in Darkshire, consider lending your abilities to The Night Watch.  Our skill is unquestionable but our numbers are small.","편히 있게, $C. 그냥 지나가는 길이라면 도로를 벗어나지 말고 낮에만 다니는 걸 권하지. 다크샤이어에 볼일이 있다면 어둠의 순찰대에 힘을 보태 주게. 실력은 의심할 여지가 없지만 인원이 너무 부족하거든."}
rows[#rows+1]={"Be careful where you put that foot of yours, $gmister:ma'am;.  We're not all blessed with the lofty height of a $r.","발밑 조심하시오, $g선생:부인;. 우리 모두가 $r처럼 훤칠한 키를 타고난 건 아니니 말이오."}
rows[#rows+1]={"Dear $g boy:girl;, you have arrived just in time to assist the Kargath Expeditionary Force.\010","소중한 $g boy:girl;아, 때맞춰 잘 왔구나. 카르가스 원정대에 네 도움이 필요하단다.\010"}
rows[#rows+1]={"Do not be alarmed, $r.  I have long since passed from this land but I intend no harm to your kind.  I have witnessed too much death in my time.  My only wish now is for peace.  Perhaps you can help my cause.","놀라지 마라, $r이여. 나는 오래전에 이 세상을 떠났으나 그대들에게 해를 끼칠 생각은 없다. 살면서 너무나 많은 죽음을 보아왔기에, 이제 내 유일한 바람은 평화뿐이다. 어쩌면 그대가 내 뜻을 도와줄 수 있을지도 모르겠구나."}
rows[#rows+1]={"Eh?  Greetings, young $C.  You're a brave one to find your way here with all those wandering creatures about!$B$BWell now that you are here, maybe you can help an old hermit...","응? 안녕하신가, 젊은 $C. 온갖 괴물들이 배회하는 이곳까지 찾아오다니 정말 용감하구먼!$B$B자, 여기까지 왔으니 이 늙은 은둔자를 좀 도와주지 않겠나..."}
rows[#rows+1]={"Good day, $glad:lass;! Perhaps you could help me with some things that need to be taken care of.","좋은 날이군, $g젊은이:아가씨;! 처리해야 할 일이 좀 있는데, 나를 도와줄 수 있겠나?"}
rows[#rows+1]={"Greetings, $C.  Be wary as you travel east toward The Bulwark.  Recent surveillance reports indicate increased Scourge activity in that area, so exercise caution.","안녕하십니까, $C. 동쪽 보루 쪽으로 이동하실 때는 주의하십시오. 최근 정찰 보고에 따르면 그 지역의 스컬지 활동이 증가했다고 하니 각별히 조심하시기 바랍니다."}
rows[#rows+1]={"Greetings, $N.","반갑소, $N."}
rows[#rows+1]={"Greetings, $N. I am Duke Nicholas Zverenhoff of the Argent Dawn.","안녕하십니까, $N. 저는 은빛여명회의 니콜라스 즈베렌호프 공작입니다."}
rows[#rows+1]={"Greetings, $R.","반갑소, $R."}
rows[#rows+1]={"Greetings, $c! Fine day for hunting, wouldn't you say? I've been having more than a little luck with boars, myself. Perhaps you'd like a shot?","반갑소, $c! 사냥하기 딱 좋은 날씨 아닌가요? 나는 멧돼지 사냥에서 꽤 쏠쏠한 재미를 보았다오. 자네도 한 번 도전해 보겠나?"}
rows[#rows+1]={"Greetings, $c.","안녕하신가, $c."}
rows[#rows+1]={"Greetings, $c.  If you're a friend of Colonel Kurzen then I'll have you cut down where you stand! but if you've come to aid us, then lend an ear...","안녕하신가, $c. 자네가 컬젠 대령의 패거리라면 그 자리에서 베어버리겠지만, 우리를 도우러 온 거라면 내 말을 들어보게나..."}
rows[#rows+1]={"Greetings, $c. I am the Flamekeeper. During the Midsummer Fire Festival, it is my duty to keep this fire beside me burning brightly. It is an honor to be selected for such a task, I fill it gladly.$b$b How can I help you?","반갑소, $c. 나는 화염의 수호자라오. 한여름 불꽃축제 기간 동안 곁에 있는 불꽃이 밝게 타오르도록 지키는 것이 내 의무지. 이런 임무에 선택받아 영광이라오. 즐거운 마음으로 임하고 있지.$b$b무엇을 도와줄까?"}
rows[#rows+1]={"Greetings, $c. I'm in a bit of a pinch right now, running very low on hides.","안녕하신가, $c. 지금 가죽이 턱없이 부족해서 골치가 좀 아픈 참이라네."}
rows[#rows+1]={"Greetings, $g lad : girl;. I'm Grelin Whitebeard. I'm here to examine the threat posed by the growing numbers of trolls in Coldridge Valley. What have I found? It's a bit troubling...","반갑네, $g청년:아가씨;. 나는 그렐린 화이트비어드라고 하네. 눈마루 골짜기에서 수가 늘어나는 트롤의 위협을 조사하러 왔지. 뭘 알아냈냐고? 조금 골치 아픈 상황이라네..."}
rows[#rows+1]={"Greetings, $n.","반갑습니다, $n."}
rows[#rows+1]={"Greetings, $n. If you bring me necrotic stones from the undead invaders, I can give you access to the stores of the Argent Dawn.","반갑소, $n. 언데드 침략자들에게서 괴사석을 가져다주면 은빛여명회의 물자를 이용할 수 있도록 해주겠소."}
rows[#rows+1]={"Hail, $C.  Ill times these are, my friend, for our town is besieged!  The Blackrock Orcs attack from Stonewatch Keep, the Shadowhides loom over the Tower of Ilgalar, and the Redridge Gnoll Pack gathers strength.  I hope you're not here for a holiday...","반갑소, $C. 친구여, 암울한 시기라오. 우리 마을이 포위당했거든! 검은바위 오크들은 돌파수 요새에서 공격해 오고, 그늘가죽 리아나들은 일갈라의 탑을 위협하고 있으며, 붉은마루 놀 무리는 세력을 키우고 있지. 휴가를 즐기러 온 게 아니길 바라오..."}
rows[#rows+1]={"Hail, $N!  Welcome to my humble garden.  The weather has been perfect lately.  Let us hope it holds steady for a ripe harvest.","반갑네, $N! 내 소박한 정원에 온 걸 환영하네. 요즘 날씨가 아주 좋았지. 풍성한 수확을 거둘 때까지 이대로 이어지면 좋겠군."}
rows[#rows+1]={"Hail, $c. In my years I have seen many eager tauren who wish to prove their worth to the tribe. It should not be forgotten that eagerness is no substitute for wisdom and experience.","반갑소, $c. 살면서 부족에 자신의 가치를 증명하고자 하는 의욕 넘치는 타우렌을 수없이 보아왔지. 의욕이 지혜와 경험을 대신할 수는 없다는 사실을 잊어서는 안 되오."}
rows[#rows+1]={"Hail, traveler.  My eyesight may be poor but I can sense the footsteps of a $c from a mile away.  For years I defended Stormwind with pride but once my eyes failed me, I was forced to retire.","반갑소, 모험가여. 눈은 잘 보이지 않지만, 1마일 밖에서도 $c의 발소리를 느낄 수 있다오. 수년간 자부심을 품고 스톰윈드를 지켜왔건만, 시력을 잃은 후로는 은퇴할 수밖에 없었지."}
rows[#rows+1]={"Hello there, $c.  Normally I'd be out on the beat looking after the folk of Stormwind, but a lot of the Stormwind guards are fighting in other lands.  So here I am, deputized and offering bounties when I'd rather be on patrol...","안녕하시오, $c. 평소라면 스톰윈드 시민들을 보살피며 순찰을 돌고 있었겠지만, 대다수 경비병들이 다른 땅에서 싸우고 있소. 그래서 순찰을 도는 대신 이렇게 현상금을 내걸고 대리 업무를 맡고 있는 거요..."}
rows[#rows+1]={"Hello, $C.  If you're here, then you must know that Silverpine is saturated with our enemies.  To survive, the Forsaken must drive them back!","반갑소, $C. 여기까지 왔다면 은빛소나무 숲이 적들로 가득 차 있다는 걸 알고 계실 거요. 포세이큰이 살아남으려면 저들을 쓸어버려야만 하오!"}
rows[#rows+1]={"Hello, $N. Perhaps you have some time to chat?","안녕하신가요, $N. 잠시 이야기 나눌 시간 있으신가요?"}
rows[#rows+1]={"Hello, citizen.  You look like a $gman:woman; with a purpose - do you have business with the Stormwind Army?","안녕하시오, 시민. 보아하니 목적이 분명한 $g남자:여자;로군. 스톰윈드 군에 볼일이 있소?"}
rows[#rows+1]={"Hello, good $gsir:lady,.  Have a seat, and a meal if you're hungry.  Don't fret if I look busy with my needlework - I'm listening to you...","안녕하세요, 좋은 $g씨: 여주님, 앉으세요, 그리고 배고픈 경우 식사를. 내가 바쁜 것 같으면 걱정하지 마세요."}
rows[#rows+1]={"Hello, hello!  Welcome to my kitchen, $g sir : m'lady;!  This is where all of the Scarlet Raven Tavern's finest delicacies are made.  Ah, just smell the wonderful aroma!","어서 오세요, $g신사:숙녀;님! 제 주방에 오신 걸 환영합니다! 이곳이 바로 붉은까마귀 여관 최고의 별미들이 탄생하는 곳이죠. 아, 이 기막힌 향기 좀 맡아 보세요!"}
rows[#rows+1]={"Hey $Gbuddy:ma'am;, do you think you could give me a hand with something?  I'm really IN dire straits here...","이봐요, $G친구:아가씨;. 혹시 나 좀 도와줄 수 있나요? 지금 정말 큰 곤경에 처해서 말이에요..."}
rows[#rows+1]={"Hey there, $N.$B$BLotwil's not the most perceptive boss I've had. He actually gets really involved with his work. So much so that sometimes his servants don't eat, or get paid.$B$B<Lucien frowns over at Lotwil.>$B$BBut that doesn't mean you should suffer.","안녕, $N.$B$B롯윌은 내가 모셨던 상사들 중 눈치가 가장 빠른 편은 아니야. 일에는 정말 깊이 빠져들지. 너무 빠진 나머지 가끔은 하인들이 밥을 먹었는지, 임금을 받았는지도 잊어버릴 정도로.$B$B<루시엔이 롯윌을 보며 얼굴을 찌푸립니다.>$B$B하지만 그렇다고 당신까지 고생할 필요는 없잖아."}
rows[#rows+1]={"How perfect of you to come by, $c.$B$BMy name is Lotwil Veriatus, founding member of the Enlightened Assembly of Arcanology, Alchemy, and Engineering Sciences: we seek to blend the intelligent sciences of Azeroth together into one comprehensive school.","마침 아주 잘 찾아오셨소, $c.$B$B제 이름은 롯빌 베리아투스, 비전학, 연금술, 공학 종합 학회의 창립 회원입니다. 우리는 아제로스의 지성 과학을 하나의 종합 학문으로 융합하는 것을 목표로 하고 있지요."}
rows[#rows+1]={"I don't have much time for idle talk, $N.  I've got to get this bridge rebuilt before the rains come.  I've finished every project on-time and under budget and I'm not about to start slipping now.","한가롭게 잡담할 시간이 없소, $N. 비가 내리기 전에 이 다리를 재건해야 하거든. 지금까지 모든 프로젝트를 제때, 예산 범위 내에서 끝마쳐왔는데 이제 와서 삐끗할 수는 없지."}
rows[#rows+1]={"I have sensed your coming for quite some time, $n.  It was written in the pattern of the stars.","당신이 올 것이라는 걸 꽤 오래전부터 느끼고 있었습니다, $n. 별들의 운명에 그렇게 적혀 있었지요."}
rows[#rows+1]={"I hope you're here to work, $C.  We have a lot to do and the Horde, the Syndicate and the Ogres aren't going to help us.","일하러 온 것이길 바라오, $C. 해야 할 일은 산더미인데 호드도, 비밀결사대도, 오거놈들도 우리를 도와주지 않을 테니 말이오."}
rows[#rows+1]={"I welcome you back, $n.","다시 온 것을 환영하네, $n."}
rows[#rows+1]={"I've got a lot going on out here in Desolace, $N. Roetten wants us to pick up some reagents for one of our clients as well as fetch some of these lost items.$B$BSeein' as you're here to help out, why don't we get started?","여기 잊혀진 땅에서 할 일이 아주 많다네, $N. 로텐은 고객 중 한 명을 위한 시약을 구하는 동시에 잃어버린 물품들도 찾아오길 원하고 있지.$B$B우리를 도우러 온 김에 바로 시작해 보는 게 어때?"}
rows[#rows+1]={"It was quite a departure, let me tell you, $c. We were grabbing whatever wasn't nailed down or could be removed quickly. We're a little spare on supplies because of it.","정말 황급한 탈출이었네, $c. 우리는 바닥에 못 박혀 있지 않거나 당장 들고 튈 수 있는 건 뭐든 챙겼지. 덕분에 물자가 좀 부족하다네."}
rows[#rows+1]={"It's dark times that have come, $c... All too soon will we lose everything... When the Light will forsake all but those who truly walk under the Light.","어두운 시기가 찾아왔습니다, $c... 머지않아 모든 것을 잃게 될 것입니다... 진정 빛의 길을 걷는 자들을 제외하고는 빛조차 모두를 버릴 때가 말입니다."}
rows[#rows+1]={"Keep the door closed, $C.  Never know when the Dark Riders will be passing through again.","문은 꼭 닫아 두게, $C. 검은 기수들이 언제 다시 지나갈지 모르니까 말이야."}
rows[#rows+1]={"Many tests await a paladin of the Light, $N. Be assured, our paths will cross many times in the future if you remain passionate and hold to those virtues that we praise.","빛의 성기사에겐 수많은 시험이 기다리고 있습니다, $N. 당신이 열정을 잃지 않고 우리가 찬양하는 덕목들을 지켜나간다면, 앞으로도 우리의 길은 수없이 교차할 것임을 확신합니다."}
rows[#rows+1]={"Pleased to meetcha, $c. Me name's Roetten. I lead Reclaimers Incorporated.$B$BMe guild and I specialize in aquiring lost goods. We usually hire brave adventurers and send them off to finish tasks for those who aren't able, or don't have the time.","만나서 반갑소, $c. 내 이름은 로텐이라고 하오. '인양 상사'를 이끌고 있지.$B$B우리 조합은 분실된 물품을 회수하는 전문이라오. 보통 용감한 모험가들을 고용해 직접 움직일 여력이 없거나 시간이 없는 사람들의 임무를 대신 처리하게 하지."}
rows[#rows+1]={"So few make it this far, even fewer make it past. Do not become a statistic, $N.","여기까지 도달하는 자도 극히 적지만, 이 너머로 살아나가는 자는 더더욱 적소. 통계 속의 한 숫자가 되지 마시오, $N."}
rows[#rows+1]={"Something I can help you with, $n? There's a shipment I've got to see to otherwise.","무슨 도움이 필요하신가요, $n? 그게 아니면 제가 확인할 화물이 있어서요."}
rows[#rows+1]={"The days grow long, and still no end to the conflicts of these lands can be seen. It takes no spell caster to know that much. Take up a blade while you can, $c. War can come to our doors at any time, and if I'm not mistaken, you look to be one who revels in it.","해는 길어지는데, 이 땅의 분쟁은 끝날 기미가 보이지 않는군요. 주문을 외우는 마법사가 아니더라도 그 정도는 알 수 있지요. 검을 들 수 있을 때 무기를 잡으십시오, $c. 전쟁은 언제든 우리 문앞까지 찾아올 수 있고, 내가 틀리지 않았다면 당신은 그걸 즐기는 사람 같아 보이는군요."}
rows[#rows+1]={"The earth calls to you, $N. Go to it, and know that your brethren are proud of you and all you will accomplish.","대지가 그대를 부르는구나, $N. 대지에게로 가라. 그리고 그대의 형제들이 그대와 그대가 이뤄낼 모든 성취를 자랑스러워하고 있음을 잊지 마라."}
rows[#rows+1]={"The heft of an axe, the battlecry of your allies, the spray of blood in your face. These are the things a warrior craves, $n. I will carve out The Barrens with my sword in the name of the Horde.","도끼의 묵직한 손맛, 동료들의 함성, 얼굴에 튀는 피보라. 이것이야말로 전사가 갈망하는 것들이다, $n. 나는 호드의 이름으로 칼을 휘둘러 불모의 땅을 개척할 것이다."}
rows[#rows+1]={"The land has been good to our people, $c. We must be thankful for our good fortune.","이 대지는 우리 부족에게 한없이 자비로웠소, $c. 우리는 이 축복에 감사해야 합니다."}
rows[#rows+1]={"There is something you wish to discuss, $c... come, sit by me.","나와 나누고 싶은 이야기라도 있소, $c... 이리 와서 내 곁에 앉으시오."}
rows[#rows+1]={"Throm'ka, $c. There is little time for talk and much work to be done.","롬카, $c. 잡담할 시간은 없으니 서둘러 일에 착수합시다."}
rows[#rows+1]={"We cannot take care of all the threats in this area alone. We could use another fighting hand, $n.","우리만으로는 이 지역의 모든 위협을 다 처리할 수 없다오. 당신 같은 싸움꾼 한 명이라도 아쉬운 상황이오, $n."}
rows[#rows+1]={"Welcome to Bonegrip's Runes and Dooms, $c.  You may look, but do not touch.$B$BSome of the knowledge here is not meant for the...uninitiated.","본그립의 룬과 파멸 상점에 오신 것을 환영합니다, $c. 구경은 해도 되지만 손대지는 마십시오.$B$B이곳의 지식 중 일부는... 초심자를 위한 것이 아니니까요."}
rows[#rows+1]={"Welcome to the Tower of Azora, young $C.  I am Theocritus.$B$BDo you have business with me?  Or...do I have business with you, perhaps?","아조라의 탑에 오신 것을 환영합니다, 젊은 $C. 저는 테오크리투스라고 합니다.$B$B제게 볼일이라도 있으신가요? 아니면... 어쩌면 제가 당신에게 볼일이 있는 걸까요?"}
rows[#rows+1]={"Well met, $C.  If you're here for business, then get yourself a brew and we'll have ourselves a talk.","반갑소, $C. 일 때문에 온 거라면 시원한 맥주 한 잔 들고 와서 얘기나 나눕시다."}
rows[#rows+1]={"Well met, $n. It is good to see that $cs like yourself are taking an active part in protecting the groves.","반갑소, $n. 당신 같은 $c들이 숲을 지키는 데 적극적으로 나서주는 모습을 보니 보기 좋군요."}
rows[#rows+1]={"Well, if it isn't a young, bristling $c, no doubt drawn here by talk of my exploits in fields of battle!$B$BNo time for stories now, for there are great, important deeds that need doing!  So if you're looking for glory, then luck shines on you today...","이거 혈기 왕성한 젊은 $c 아니신가. 전장에서 내가 세운 공훈 이야기를 듣고 찾아온 게 틀림없군!$B$B지금은 한가하게 옛날이야기나 할 때가 아니네. 해야 할 위대하고 중요한 일들이 아주 많거든! 그러니 영광을 꿈꾸고 있다면, 오늘 운이 아주 좋은 줄 알게나..."}
rows[#rows+1]={"Whatcha need, $c?  I trust that you've come out to this wasteland for a reason other than idle chit chat.","무슨 일인가, $c? 한가한 잡담이나 하러 이 황무지까지 찾아온 건 아니리라 믿네."}
rows[#rows+1]={"Who is this $c who goes before the Court of Lakshire in the Kingdom of Stormwind?  State your business within this township, $R.  The orc threat to the Kingdom is far too great to squander time in idle conversation.","이 스톰윈드 왕국 레이크샤이어 법정 앞에 선 $c은 누구인가? 이 마을에 무슨 볼일이 있는지 밝히시오, $R. 오크의 위협이 너무 심각해서 한가한 잡담에 시간을 낭비할 수 없소."}
rows[#rows+1]={"Yes yes yes!  You're just the $r I'm looking for!$B$BSit!  We have much to discuss!!","그래, 그래, 좋아! 자네가 바로 내가 찾던 $r이로군!$B$B앉게! 이야기할 게 아주 많아!!"}
rows[#rows+1]={"You must be hard up to be wandering these Badlands, $c.  Hard up like me.$B$BOr maybe you're here because you're crazy.  Crazy, like me.","이 황탄한 황야를 배회하는 걸 보니 자네도 궁지에 몰린 게 틀림없군, $c. 나처럼 말이야.$B$B아니면 미쳐서 여기까지 온 걸지도 모르지. 미친 나처럼."}
rows[#rows+1]={"You must listen, young $c.  Listen to the whisperings in the darkness, for they offer guidance in these troubled times.","잘 듣게, 젊은 $c. 어둠 속의 속삭임에 귀 기울이게나. 이 혼란스러운 시기에 가르침을 줄 테니."}
rows[#rows+1]={"You watch where you step around here, $Gson:lass;.  You might not be a part of our outfit, but that doesn't mean I won't take a cane to you if you fall out of line!","여기선 발밑 조심해, $G젊은이:아가씨;. 우리 패거리가 아니라고 봐주는 건 아니야. 선 넘으면 지팡이 맛 좀 보여줄 테니까!"}
rows[#rows+1]={"You will be tested many times by the darkness that surrounds our lands, $N. But to ensure you are always prepared, we will often ask tasks of you so you are at the height of your own power.$B$BGo with the Light, and remain virtuous.","우리 땅을 둘러싼 어둠에 수없이 시험받게 될 것입니다, $N. 하지만 항상 준비된 자세를 유지할 수 있도록, 당신이 스스로의 힘을 극대화할 수 있는 과업들을 종종 내릴 것입니다.$B$B빛과 함께하시고, 덕을 잃지 마십시오."}
